#include <bits/stdc++.h>
using namespace std;

vector<int> primes;

void generate_primes() {
    for (int p = 2; p < 6000; p++) {
        bool is_prime = true;
        for (int p2 : primes) {
            if (p2 * p2 > p) break;
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes.push_back(p);
        }
    }
}

map<long long, int> factor(long long n) {
    map<long long, int> factors_dict;
    for (int p : primes) {
        long long p_ll = p;
        if (p_ll * p_ll > n) break;
        if (n % p_ll == 0) {
            int count = 0;
            while (n % p_ll == 0) {
                n /= p_ll;
                count++;
            }
            factors_dict[p_ll] = count;
        }
    }
    if (n > 1) {
        factors_dict[n] = 1;
    }
    return factors_dict;
}

vector<long long> get_factors(long long n) {
    auto prime_factors = factor(n);
    vector<long long> result = {1};
    for (auto &pf : prime_factors) {
        long long p = pf.first;
        int count = pf.second;
        vector<long long> new_list;
        for (auto val : result) {
            for (int i = 0; i <= count; i++) {
                long long val_new = val;
                for (int j = 0; j < i; j++) {
                    val_new *= p;
                }
                new_list.push_back(val_new);
            }
        }
        result = new_list;
    }
    return result;
}

long long compute(int n, int m) {
    vector<long long> f(n + 1);
    f[0] = 0;
    if (n >= 1) f[1] = 1;
    if (n >= 2) f[2] = 2;
    for (int i = 3; i <= n; i++) {
        f[i] = 2 * f[i - 1];
        auto factors_list = get_factors(i);
        for (auto &x : factors_list) {
            if (x >= 2 && x <= i) {
                long long term = f[i / x] - f[(i - 1) / x];
                f[i] = (f[i] + term) % m;
            }
        }
        f[i] %= m;
    }
    return f[n];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    generate_primes();
    int n, m;
    cin >> n >> m;
    cout << compute(n, m) << "\n";
    return 0;
}

